package dev.koikaster.mite;
import net.minecraft.core.*;
import net.minecraft.tags.BlockTags;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.monster.Blaze;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraftforge.registries.ForgeRegistries;
/** nn base-tick fire spreading and listed source block melt/burn tables; no invented mobGriefing gate. */
public final class OriginalFireSpread {
 private static boolean scoped(Entity entity){var key=ForgeRegistries.ENTITY_TYPES.getKey(entity.getType());return key!=null&&(key.getNamespace().equals("minecraft")||key.getNamespace().equals(MiteReforged.ID));}
 public static float chance(Entity entity){if(Mobs.name(entity).equals("fire_elemental"))return .05f;if(entity instanceof Mobs.Undead earth&&earth.earthBody()&&earth.originalEarth().magma()||entity instanceof Blaze||entity instanceof SourceMagmaCube)return .04f;return entity.isOnFire()?entity instanceof Mob mob&&((SourceFireMobState)mob).mite$fireSpreadTicks()>0?.01f:.00125f:0;}
 public static void mobTick(Object raw){var mob=(Mob)raw;var state=(SourceFireMobState)mob;if(!mob.level().isClientSide&&state.mite$fireSpreadTicks()>0)state.mite$fireSpreadTicks(state.mite$fireSpreadTicks()-1);}
 public static int flammability(BlockState block,net.minecraft.world.level.BlockGetter level,BlockPos pos){if(block.is(BlockTags.PLANKS)||block.is(BlockTags.WOODEN_SLABS)||block.is(BlockTags.WOODEN_STAIRS)||block.is(BlockTags.WOODEN_FENCES))return block.getFlammability(level,pos,Direction.UP)>0?20:0;if(block.is(BlockTags.LOGS_THAT_BURN))return 5;if(block.getBlock() instanceof LeavesBlock||block.is(BlockTags.WOOL))return 60;if(block.is(Blocks.BOOKSHELF))return 20;if(block.is(Blocks.TNT)||block.is(Blocks.GRASS)||block.is(Blocks.TALL_GRASS)||block.is(Blocks.FERN)||block.is(Blocks.LARGE_FERN)||block.is(Blocks.HAY_BLOCK)||block.is(Blocks.COBWEB)||block.is(Blocks.WHEAT)||block.is(Blocks.DEAD_BUSH)||block.getBlock() instanceof VineBlock)return 100;if(block.is(Blocks.COAL_BLOCK))return 5;if(block.getBlock() instanceof SugarCaneBlock||Content.id("bush").equals(ForgeRegistries.BLOCKS.getKey(block.getBlock())))return 50;return 0;}
 public static int encouragement(BlockState block,net.minecraft.world.level.BlockGetter level,BlockPos pos){int burn=flammability(block,level,pos);if(burn==0)return 0;if(block.is(Blocks.TNT)||block.getBlock() instanceof VineBlock)return 15;if(block.getBlock() instanceof LeavesBlock||block.is(BlockTags.WOOL)||block.is(Blocks.BOOKSHELF)||block.getBlock() instanceof SugarCaneBlock||Content.id("bush").equals(ForgeRegistries.BLOCKS.getKey(block.getBlock())))return 30;return burn==100?60:5;}
 public static boolean hasFuelAdjacent(net.minecraft.world.level.BlockGetter level,BlockPos pos){for(var direction:new Direction[]{Direction.EAST,Direction.WEST,Direction.DOWN,Direction.UP,Direction.NORTH,Direction.SOUTH}){var next=pos.relative(direction);var block=level.getBlockState(next);if(block.is(Blocks.NETHERRACK)||encouragement(block,level,next)>0)return true;}return false;}
 public static boolean survives(Object raw,Object at){var level=(net.minecraft.world.level.LevelReader)raw;var pos=(BlockPos)at;var below=level.getBlockState(pos.below());return raw instanceof Level world&&world.dimension()==Level.END&&below.is(Blocks.BEDROCK)||below.is(Blocks.GRASS_BLOCK)||below.is(Blocks.NETHERRACK)||hasFuelAdjacent(level,pos);}
 public static boolean catchBlock(Entity actor,BlockPos pos){var level=actor.level();var block=level.getBlockState(pos);var random=((SourceFireRandom)actor).mite$fireRandom();if(random.nextInt(100)<flammability(block,level,pos)){boolean tnt=block.is(Blocks.TNT);if(random.nextInt(11)<5&&!OriginalWeather.rain(level,pos)){int age=Math.min(1+random.nextInt(5)/4,15);level.setBlock(pos,Blocks.FIRE.defaultBlockState().setValue(FireBlock.AGE,age),3);}else level.removeBlock(pos,false);if(tnt)TntBlock.explode(level,pos);return true;}return false;}
 public static boolean melt(Level level,BlockPos pos){var state=level.getBlockState(pos);if(state.is(Blocks.ICE))return level.setBlock(pos,Blocks.WATER.defaultBlockState(),3);if(state.is(Blocks.SNOW_BLOCK))return level.setBlock(pos,Blocks.SNOW.defaultBlockState().setValue(SnowLayerBlock.LAYERS,7),3);if(state.is(Blocks.SNOW)){int layers=state.getValue(SnowLayerBlock.LAYERS);return layers==1?level.removeBlock(pos,false):level.setBlock(pos,state.setValue(SnowLayerBlock.LAYERS,layers-1),3);}return false;}
 private static BlockPos resting(Entity actor){if(!actor.onGround()||actor.isPassenger())return null;var box=actor.getBoundingBox();BlockPos selected=null;double best=0;for(int x=net.minecraft.util.Mth.floor(box.minX);x<=net.minecraft.util.Mth.floor(box.maxX-.001);x++)for(int z=net.minecraft.util.Mth.floor(box.minZ);z<=net.minecraft.util.Mth.floor(box.maxZ-.001);z++)for(int y=net.minecraft.util.Mth.floor(box.minY)-1;y<=net.minecraft.util.Mth.floor(box.maxY-.001);y++){var pos=new BlockPos(x,y,z);var shape=actor.level().getBlockState(pos).getCollisionShape(actor.level(),pos,CollisionContext.of(actor));if(shape.isEmpty()||shape.bounds().maxY+y!=box.minY)continue;double dx=x+.5-actor.getX(),dz=z+.5-actor.getZ(),distance=dx*dx+dz*dz;if(selected==null||distance<best){selected=pos;best=distance;}}return selected;}
 public static void tick(Object raw){var actor=(Entity)raw;if(actor.level().isClientSide||!scoped(actor))return;if(actor instanceof Mobs.Undead mob)mob.originalEnvironment().wetTick();float chance=chance(actor);if(chance<=0)return;var random=((SourceFireRandom)actor).mite$fireRandom();if(random.nextFloat()>=chance)return;var feet=actor.blockPosition();for(int dy=0;dy<(int)actor.getBbHeight()+1;dy++){var at=feet.above(dy);var block=actor.level().getBlockState(at);if(block.isAir()){if(random.nextInt(10)==0&&hasFuelAdjacent(actor.level(),at)){actor.level().setBlock(at,Blocks.FIRE.defaultBlockState(),3);continue;}if(dy==0){var support=resting(actor);if(support!=null)melt(actor.level(),support);}}else if(!catchBlock(actor,at))melt(actor.level(),at);}}
 private OriginalFireSpread(){}
}
